import java.util.*;

public class Main {
    int[] dailyTemperatures(int[] temps) {
        int[] result = new int[temps.length];
        Deque<Integer> stack = new ArrayDeque<>();                                    // a monotonic DECREASING stack of day-indices still awaiting warmth
        for (int i = 0; i < temps.length; i++) {
            while (!stack.isEmpty() && temps[stack.peek()] < temps[i]) {                // today is warmer than everything waiting on top
                int idx = stack.pop();
                result[idx] = i - idx;                                                    // the WAIT is simply the gap in days (index difference)
            }
            stack.push(i);
        }
        return result;                                                                   // anything left on the stack never got warmer (stays 0)
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[] temps = {73, 74, 75, 71, 69, 72, 76, 73};
        System.out.println(Arrays.toString(solution.dailyTemperatures(temps)));
    }
}

